const esperar = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

await esperar(500);
console.log("pasaron 500 ms"); // pasaron 500 ms

let cargando = true;
Promise.reject(new Error("x"))
  .catch(() => console.log("hubo error")) // hubo error
  .finally(() => {
    cargando = false;
    console.log(cargando); // false
  });

const pedir = (v, ms) => new Promise((r) => setTimeout(() => r(v), ms));

const [a, b] = await Promise.all([
  pedir("A", 300),
  pedir("B", 100),
]);
console.log(a, b); // A B (en unos 300 ms, no 400: corren en paralelo)

const res = await Promise.allSettled([
  Promise.resolve(1),
  Promise.reject(new Error("caída")),
]);
console.log(res.map((r) => r.status)); // ["fulfilled", "rejected"]
console.log(res[0].value, res[1].reason.message); // 1 caída

const limite = (ms) => new Promise((_, rej) =>
  setTimeout(() => rej(new Error("tardó demasiado")), ms));
const lenta = new Promise((r) => setTimeout(() => r("datos"), 2000));
try {
  await Promise.race([lenta, limite(500)]);
} catch (e) {
  console.log(e.message); // tardó demasiado
}

const r = await Promise.any([
  Promise.reject(new Error("servidor 1 caído")),
  Promise.resolve("respuesta del servidor 2"),
]);
console.log(r); // respuesta del servidor 2

async function doble(n) {
  return n * 2;
}
console.log(doble(4)); // Promise { 8 }
doble(4).then((v) => console.log(v)); // 8
console.log(await doble(4)); // 8

const pedir = (v) => new Promise((r) => setTimeout(() => r(v), 100));

async function main() {
  const usuario = await pedir("Ana");
  console.log(usuario); // Ana
}
main();

// dentro de una función async (o en un módulo)
try {
  await Promise.reject(new Error("404"));
} catch (e) {
  console.log("Error:", e.message); // Error: 404
} finally {
  console.log("fin"); // fin
}

console.log("1");
setTimeout(() => console.log("3"), 0);
console.log("2");
// imprime 1, 2, 3: aunque sea 0 ms, espera a que termine el código actual
const id = setTimeout(() => console.log("nunca"), 1000);
clearTimeout(id); // cancelado

let n = 0;
const id = setInterval(() => {
  n++;
  console.log("tick", n); // tick 1, tick 2, tick 3
  if (n === 3) clearInterval(id);
}, 100);

setTimeout(() => console.log("timeout"), 0);
queueMicrotask(() => console.log("microtarea"));
Promise.resolve().then(() => console.log("then"));
console.log("síncrono");
// síncrono, microtarea, then, timeout

async function getUsuario(id) {
  const res = await fetch(`/api/usuarios/${id}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return await res.json();
}
console.log(await getUsuario(1)); // { id: 1, nombre: "Ana" }
